// Compatibility profiles: the USB identity and AAGUID a build presents to the
// host. Upstream ships exactly one identity (a documented non-MDS AAGUID); the
// research fork lets the operator choose a modelled commercial authenticator so
// a relying party's classifier can be studied per model.
//
// A profile is *presentation only*. Nothing here changes key custody: every
// credential is still generated by the configured backend (Secure Enclave, TPM
// or software) and attested by a self-signed certificate, never by a vendor key.
#pragma once

#include <array>
#include <cstdint>
#include <memory>
#include <mutex>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace swpk::compat {

using Aaguid = std::array<std::uint8_t, 16>;

// How the 16-character HID serial is derived. `sidecar` is upstream behaviour
// (random hex, generated once). `decimal8` renders the same stored seed as the
// eight decimal digits a commercial key reports, so it stays stable across
// launches and unique per install.
enum class SerialStrategy : std::uint8_t { sidecar, decimal8 };

struct CompatProfile {
  std::string id;    // stable key used by the control socket and the sidecar
  std::string name;  // menu bar label
  Aaguid aaguid{};
  std::string aaguid_str;  // canonical 8-4-4-4-12 UUID, for logs and MDS lookups
  std::uint16_t vid{};
  std::uint16_t pid{};
  std::uint16_t bcd_device{0x0001};
  std::string manufacturer;
  std::string product;
  // What authenticatorGetInfo(0x04).transports reports (key 0x09). Chrome copies
  // this into AuthenticatorAttestationResponse.getTransports(), which the site
  // serialises into the registration POST, so it is a client-visible claim.
  std::vector<std::string> transports{"usb"};
  SerialStrategy serial{SerialStrategy::sidecar};

  // Attestation certificate subject fields (self-attestation only).
  std::string att_cn;
  std::string att_ou;
  std::string att_o;
  std::string att_c;

  // Free-form note surfaced in `swpasskeyctl profiles` and the About pane, so a
  // misleading result is never mistaken for a certified device.
  std::string note;

  // Upstream's own identity: not in the FIDO MDS, not a commercial model.
  bool stock() const { return id == "stock-swpasskey"; }
};

// 8-4-4-4-12 lowercase UUID text.
std::string aaguid_to_string(const Aaguid& a);
// Accepts 8-4-4-4-12 with or without dashes/braces, any case.
std::optional<Aaguid> aaguid_from_string(std::string_view text);

// Registry, in menu order. Static storage: safe to hold the pointers.
const std::vector<CompatProfile>& all_profiles();
const CompatProfile* find_profile(std::string_view id);
// Upstream identity (stock-swpasskey); also the fallback for an unknown id.
const CompatProfile& default_profile();

// Profile-specific serial rendering. `seed_hex` is the stored sidecar value;
// the result is stable for a given (profile, seed) pair.
std::string serial_for(const CompatProfile& profile, std::string_view seed_hex);

// Process-wide selected profile. The daemon mutates it from the control socket
// while the HID and CTAP threads read it, so access is guarded and readers take
// a shared_ptr copy instead of a reference.
class Identity {
public:
  Identity() : profile_(std::make_shared<const CompatProfile>(default_profile())) {}

  std::shared_ptr<const CompatProfile> profile() const {
    std::lock_guard<std::mutex> lk(mu_);
    return profile_;
  }

  // Monotonic; the HID loop uses it to decide when to re-enumerate.
  std::uint64_t generation() const {
    std::lock_guard<std::mutex> lk(mu_);
    return generation_;
  }

  // Returns the previous generation so the caller can tell whether anything
  // changed (same profile re-selected = no re-enumeration).
  std::uint64_t set(std::shared_ptr<const CompatProfile> p) {
    std::lock_guard<std::mutex> lk(mu_);
    if (p != nullptr && profile_ != nullptr && p->id == profile_->id) {
      return generation_;
    }
    profile_ = std::move(p);
    return ++generation_;
  }

private:
  mutable std::mutex mu_;
  std::shared_ptr<const CompatProfile> profile_;
  std::uint64_t generation_{1};
};

}  // namespace swpk::compat
